// Bundle the SiteOps engine into ONE Deno-importable ESM file for the edge functions.
//
// Why: Deno 2 requires explicit .ts extensions on relative imports, but the engine
// (src/lib/siteOps/engine) uses extensionless internal imports for the Vite/Node side. Rather than
// touch the green M1–M5 source, we esbuild the barrel into a single self-contained file with no
// internal imports, which Deno imports directly. Regenerate whenever the engine changes:
//
//   node scripts/build-engine-bundle.mjs
//
// Output: supabase/functions/_shared/siteops-engine.js  (committed; pure, no Node/Deno APIs).
import { build } from 'esbuild'
import { fileURLToPath } from 'node:url'
import path from 'node:path'

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const entry = path.join(root, 'src/lib/siteOps/engine/index.ts')
const outfile = path.join(root, 'supabase/functions/_shared/siteops-engine.js')

await build({
  entryPoints: [entry],
  outfile,
  bundle: true,
  format: 'esm',
  platform: 'neutral',   // pure engine — no Node/Deno builtins
  target: 'es2022',
  banner: { js: '// GENERATED by scripts/build-engine-bundle.mjs — do not edit. Source: src/lib/siteOps/engine/' },
  logLevel: 'info',
})
console.log('wrote', path.relative(root, outfile))
